'QZ_Tray_Printer' => 'QZ Tray (bu kompüterdəki printer)',
'QZ_Printer_Name_Hint' => 'QZ Tray işləyən kompüterdə göründüyü kimi printerin adı. Həmin kompüterin defolt printerindən istifadə etmək üçün boş buraxın. Printerləri aşkar etmək üçün ⟳ düyməsinə klikləyin.',
'QZ_Not_Running' => 'QZ Tray bu kompüterdə işləmir. Onu qz.io saytından quraşdırın və işlək saxlayın, sonra QZ soruşduqda bu sayta icazə verin.',
'Detect_Printers' => 'Printerləri aşkar et',
'QZ_Download_Cert' => 'Sertifikatı yüklə (override.crt)',
'QZ_Setup_Title' => 'QZ Tray çapını necə qurmaq olar (bir dəfə, etiket çap edən hər kompüterdə)',
'QZ_Step_Install' => '1. QZ Tray-i bu kompüterə quraşdırın — onu qz.io saytından pulsuz yükləyin, sonra işə salın və işlək vəziyyətdə saxlayın (Windows-da sistem lövhəsində, macOS-da menyu panelində yerləşir).',
'QZ_Step_Connect' => '2. Etiket printerinizi USB ilə qoşun və onun əməliyyat sistemində quraşdırıldığını yoxlayın (Windows: Parametrlər > Printerlər və skanerlər — macOS: Sistem parametrləri > Printerlər və skanerlər).',
'QZ_Step_Detect' => '3. Bu kompüterdəki printerləri aşkar etmək üçün yuxarıda "Printerin adı" yanındakı ⟳ düyməsinə klikləyin, sonra etiket printerinizi seçin. Kompüterin defolt printerindən istifadə etmək üçün sahəni boş buraxın.',
'QZ_Step_Cert' => '4. İcazə pəncərəsi olmadan çap etmək üçün aşağıdakı sertifikatı yükləyin və adını override.crt olaraq dəyişib QZ Tray quraşdırma qovluğuna kopyalayın (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Sonra QZ Tray-i bağlayın və yenidən işə salın.',
'QZ_Step_Test' => '5. Aşağıdakı "Test etiketini çap et" düyməsinə klikləyin. QZ Tray icazə istəsə, İcazə ver düyməsinə klikləyin — sertifikat quraşdırıldıqda bir daha soruşmayacaq.',
'QZ_Step_Save' => '6. Bu parametrləri saxlamaq üçün Göndər düyməsinə klikləyin. Barkod çapı səhifəsindən etiketlər indi brauzer çap pəncərəsi olmadan birbaşa bu printerdə çap olunacaq.',
'QZ_Setup_Note' => 'QZ Tray baxış etdiyiniz kompüterdə işləyir, ona görə də Stocky uzaq serverdə yerləşdikdə belə bu işləyir. Etiket çap edən hər kompüterdə QZ Tray quraşdırılmalıdır.',

