'Ord_Guide_MarkPaid_Step1' => 'Əvvəlcə sifarişi burada təsdiqləyin — satışı yaradan təsdiqdir.',
'Ord_Guide_MarkPaid_Step2' => 'Satışlar > Bütün satışlar bölməsini açın və həmin satışı tapın (eyni müştəri, təfərrüatlar səhifəsi isə onun yarandığı onlayn sifarişi göstərir).',
'Ord_Guide_MarkPaid_Step3' => 'Sətir əməliyyatları menyusunu açın və Ödəniş yarat seçin.',
'Ord_Guide_MarkPaid_Step4' => 'Məbləği, ödəniş üsulunu və tarixi daxil edin, sonra saxlayın. Satış məbləğdən asılı olaraq avtomatik Qismən və ya Ödənilib vəziyyətinə keçir.',
'Ord_Guide_MarkPaid_Note' => 'Burada göstərilən Ödəniş statusu ödəniş zamanı edilən seçimi qeyd etməyə davam edir və olduğu kimi qalır. Mühasibat qeydi satışdır və ödəniş və mənfəət hesabatlarınızı qidalandıran odur. Daxil etdiklərinizi nəzərdən keçirmək və ya redaktə etmək üçün satışda Ödənişləri göstər seçimindən istifadə edin.',
'Ord_Guide_Notes_Title' => 'Bilmək faydalıdır',
'Ord_Guide_Note_Warehouse' => 'Təsdiq zamanı seçdiyiniz anbar stokun haradan götürüləcəyini müəyyən edir. Bütün sifarişi təmin edə bilməyən anbarlar həmin siyahıda Stokda yoxdur kimi işarələnir.',
'Ord_Guide_Note_Preorder' => 'Əvvəlcədən sifariş məhsulları stok yoxlamasını keçir, ona görə də onları ehtiva edən sifariş miqdar hələ mövcud olmasa belə təsdiqlənə bilər.',
'Ord_Guide_Note_Flagged' => 'İşarələnib teqi sifarişin ödəniş zamanı fırıldaqçılıq yoxlamasına düşdüyünü bildirir. Səbəbi görmək üçün kursoru teqin üzərinə gətirin və təsdiqləməzdən əvvəl sifarişi nəzərdən keçirin.',
'Ord_Guide_Note_Cancel' => 'Ləğv yalnız sifariş hələ gözləmədə olduqda mümkündür. Təsdiqləndikdən sonra onu satış və ya müştəri qaytarması vasitəsilə geri çevirin.',


