'VG_Rows_Title' => 'Variant sətirləri',
'VG_Rows_Text' => 'Hər sətirdə şəkil, kod, barkod, maya dəyəri, qiymət, topdan qiymət və minimum satış qiyməti var. Məhsul yaradarkən hər variant üçün anbar üzrə ilkin stoku da daxil edə bilərsiniz. "Natamam" teqi sətirdə bir seçim üçün dəyərin olmadığını bildirir.',
'VG_List_Title' => 'Sadə siyahı rejimi',
'VG_List_Text' => 'Sətir əlavə etmək üçün variant adını yazın və Enter basın (və ya Əlavə et düyməsinə klikləyin), sonra onun kodunu və qiymətlərini doldurun. Bu, klassik davranışdır və mövcud məhsullar üçün əlçatan qalır.',
'VG_Edit_Title' => 'Sonradan redaktə',
'VG_Edit_1' => 'Dəyər əlavə edin və "Variantları yarat" düyməsinə klikləyin: yalnız çatışmayan kombinasiyalar əlavə olunur. Mövcud sətirlər kodlarını, qiymətlərini və tarixçəsini saxlayır.',
'VG_Edit_2' => 'Dəyərin və ya seçimin silinməsi ondan istifadə edən sətirləri silir. Artıq saxlanmış sətirlər məhsulu saxladığınız zaman təsdiqdən sonra silinir.',
'VG_Edit_3' => 'Hələ stoku olan variant silinə bilməz. Əvvəlcə onun stokunu düzəldin və ya köçürün.',
'VG_Edit_4' => '"Sadə siyahı"ya keçid sətirləri və onların adlarını saxlayır, lakin seçim təriflərini silir.',
'VG_Store_Title' => 'Onlayn mağazada',
'VG_Store_Text' => 'Müştərilər hər seçim üçün bir dəyər seçir, məsələn əvvəlcə Rəng, sonra Ölçü. Mövcud olmayan kombinasiyalar deaktiv edilir, stokda olmayanların üstündən xətt çəkilir. Səbətə seçilmiş variant əlavə olunur.',
