'Upd_Guide_Before_Download' => 'Tətbiqin {package} CodeCanyon hesabınızdan ({path}) endirin. Onu arxivdən çıxarmayın — yeniləyiciyə ZIP məhz endirildiyi kimi lazımdır.',
