'Upd_Guide_Before_Quiet' => 'Sakit bir vaxt seçin: yeniləmə zamanı tətbiq qısa müddətə texniki xidmət rejiminə keçir və digər istifadəçilər daxil ola bilmir.',
'Upd_Guide_Before_No_Manual' => 'Əl ilə ehtiyat nüsxə çıxarmağa, faylları arxivdən çıxarmağa, əmrlər işə salmağa, konfiqurasiya fayllarını redaktə etməyə və ya verilənlər bazasına toxunmağa ehtiyacınız {not} — yeniləyici bunların hamısını avtomatik edir. (Əlavə əl ilə ehtiyat nüsxə, əlbəttə, heç vaxt zərər vermir.)',
'Upd_Not' => 'yoxdur',
'Upd_Guide_Code_Overwritten' => 'Tətbiq kodunu əl ilə dəyişdirmisinizsə, dəyişiklikləriniz yeniləmə ilə üzərinə yazılacaq. Məlumatlarınız, yükləmələriniz, parametrləriniz və .env həmişə qorunur.',
