'Upd_Guide_Run_Upload' => '{upload}: endirilmiş paketi yükləmə xanasına klikləyin və ya sürükləyin. Böyük fayllar kiçik hissələrlə yüklənir, buna görə bu, aşağı yükləmə limitləri olan paylaşılan hostinqdə də işləyir. Yoxlama cəmi zədələnmiş və ya natamam yükləmələrdən qoruyur.',
'Upd_Upload_The_Zip' => 'ZIP-i yükləyin',
'Upd_Guide_Run_Validation' => '{auto} yükləmədən sonra ({button} düyməsi ilə yenidən işə sala bilərsiniz). Sistem yoxlayır: ZIP bütövlüyü, paketin strukturu və tamlığı, versiya uyğunluğu (aşağı versiyaya keçid rədd edilir), tələb olunan PHP versiyası və genişlənmələri, fayl icazələri, boş disk sahəsi, verilənlər bazası bağlantısı, konfiqurasiya və başqa yeniləmənin işləmədiyi.',
'Upd_Validation_Runs_Automatically' => 'Yoxlama avtomatik işləyir',
'Upd_Guide_Run_Review' => '{panel} panelini nəzərdən keçirin. {button} düyməsi yalnız bütün kritik yoxlamalar keçdikdə görünür. Yoxlama uğursuz olarsa, mesaj nəyi düzəltməli olduğunuzu dəqiq bildirir.',
'Upd_Guide_Run_Click' => '{button} düyməsinə klikləyin və təsdiqləyin. Sonra sadəcə {keep} və irəliləyiş xəttini izləyin. Sistem ardıcıllıqla bunları yerinə yetirir:',
'Upd_Keep_Page_Open' => 'bu səhifəni açıq saxlayın',
'Upd_Guide_Phase_Backup' => '{label} — tam verilənlər bazası dampı, yeniləmənin dəyişə biləcəyi bütün tətbiq fayllarının ZIP-i və {env} faylının nüsxəsi yaradılır və {verified}. Yükləmələrinizə ({images}) və {storage} qovluğuna yeniləmə heç vaxt toxunmur, buna görə onlar arxivləşdirilmir. Ehtiyat nüsxə yaradıla bilməzsə, yeniləmə burada dayanır və heç nə dəyişmir.',
'Upd_Verified' => 'yoxlanılır',
'Upd_Guide_Phase_Prepare' => '{label} — yeni versiya hazırlıq sahəsinə çıxarılır və yenidən yoxlanılır. Canlı tətbiqə hələ toxunulmur.',
'Upd_Guide_Phase_Maintenance' => '{label} — texniki xidmət rejimi aktivləşdirilir; ziyarətçilər mehriban "Tezliklə qayıdacağıq" ekranını görür.',
'Upd_Guide_Phase_Files' => '{label} — yeni fayllar demək olar ki, dərhal yerinə qoyulur; köhnə fayllar geri qaytarma üçün kənarda saxlanılır. Qorunan yollar ({env}, {storage}, {images}) heç vaxt əvəz edilmir.',
