'Upd_Guide_Phase_Cache' => '{label} — bütün keşlər təmizlənir və yenidən qurulur.',
'Upd_Guide_Phase_Verify' => '{label} — sağlamlıq yoxlamaları yeni versiyanın işə düşdüyünü, verilənlər bazasının işlədiyini, bütün miqrasiyaların icra edildiyini və konfiqurasiyanın düzgün olduğunu təsdiqləyir.',
'Upd_Guide_Phase_Done' => '{label} — texniki xidmət rejimi götürülür və müvəqqəti fayllar təmizlənir.',
'Upd_Guide_Run_Success' => '{success} gördükdə, {reload} düyməsinə klikləyin və yeni admin paneli resurslarının yüklənməsi üçün brauzerinizi tam yeniləyin ({keys}).',
'Upd_Update_Successful_Short' => 'Yeniləmə uğurlu oldu',
'Upd_Guide_No_Internet' => 'Yeniləmə zamanı internet bağlantısı tələb olunmur — hər şey yüklənmiş ZIP-dən gəlir. Bağlantının itməsi və ya brauzerin bağlanması yeniləməni POZMUR: server harada dayandığını dəqiq yadda saxlayır.',
'Upd_Guide_Wrong_Title' => '3. Nəsə səhv gedərsə',
'Upd_Guide_Wrong_Rollback' => '{label} — fayllar dəyişməyə başladıqdan sonra nəsə uğursuz olarsa (çıxarma xətası, miqrasiya uğursuzluğu, uğursuz sağlamlıq yoxlaması, dolu disk, …), sistem əvvəlki faylları və verilənlər bazasını yoxlanılmış ehtiyat nüsxədən avtomatik bərpa edir, texniki xidmət rejimini götürür və {message} bildirir. Başladığınız yerə tam qayıdırsınız.',
'Upd_Automatic_Rollback' => 'Avtomatik geri qaytarma',
'Upd_Failed_Previous_Restored' => 'Yeniləmə uğursuz oldu — əvvəlki versiya bərpa edildi',
'Upd_Guide_Wrong_Interrupted' => '{label} (serverin yenidən başladılması, vaxt aşımı, bağlanmış brauzer, elektrik kəsilməsi) — bu səhifəni yenidən açdıqda, qırmızı banner iki təhlükəsiz seçim təklif edir: {resume} (dayandığı dəqiq addımdan davam edir) və ya {rollback} (əvvəlki versiyanı ehtiyat nüsxədən bərpa edir).',
'Upd_Interrupted_Update' => 'Kəsilmiş yeniləmə',
'Upd_Guide_Wrong_Unreachable' => '{label} — {path} ünvanındakı müstəqil {console} istifadə edin. O, sayt texniki xidmət rejimində olduqda və ya admin paneli resursları pozulduqda belə işləyir və eyni Davam et / Geri qaytar əməliyyatlarını təklif edir. Texniki xidmət ekranının aşağısında diskret "Administrator girişi" keçidi də var.',
'Upd_Admin_Unreachable' => 'Admin paneli əlçatmazdır',
'Upd_Recovery_Console' => 'bərpa konsolundan',
'Upd_Guide_Wrong_Locked_Out' => '{label} — yeniləmə işləyərkən bu səhifə {link} göstərir. Yenidən daxil olmağınız lazım olarsa (məsələn, sessiyanız bitdikdən sonra) onu saxlayın; o, sizi texniki xidmət ekranından keçirir ki, yenidən daxil ola biləsiniz.',
'Upd_Locked_Out_Maintenance' => 'Texniki xidmət rejimi səbəbindən giriş bağlanıb',
'Upd_Bypass_Link' => 'yan keçmə keçidi',
'Upd_Guide_Wrong_Concurrent' => '{label} — onlar {message} görəcəklər. Eyni anda yalnız bir yeniləmə işləyə bilər.',
'Upd_Another_Admin_Updating' => 'Başqa admin eyni vaxtda yeniləməyə çalışır',
'Upd_Guide_Backups_Title' => '4. Ehtiyat nüsxələr və bərpa',
'Upd_Guide_Backups_Created' => 'Hər yeniləmə hər hansı şeyə toxunmazdan {before} ehtiyat nüsxə yaradır: yeniləmənin əvəz edə biləcəyi bütün tətbiq faylları, {env} faylının nüsxəsi və tam verilənlər bazası dampı. Yükləmələr və {storage} yeniləmə ilə heç vaxt dəyişdirilmir və buna görə də ona daxil deyil — onların ehtiyat nüsxələrini özünüz saxlayın. Ehtiyat nüsxələr {path} yolunda saxlanılır və vebdən heç vaxt əlçatan deyil.',
'Upd_Before' => 'əvvəl',
'Upd_Guide_Backups_Panel' => '{tab} tabındakı {panel} paneli onları tarix, versiya və ölçü ilə sadalayır. Oradan istənilən tam ehtiyat nüsxəni {restore} (fayllar + verilənlər bazası — əvvəlcə cari verilənlər bazasının təhlükəsizlik nüsxəsi götürülür) və ya köhnələrini {delete} bilərsiniz.',
'Upd_Restore_Verb' => 'bərpa edə',
'Upd_Delete_Verb' => 'silə',
'Upd_Guide_Backups_Retention' => 'Neçə ehtiyat nüsxənin saxlanılacağını seçmək üçün {keep} istifadə edin; köhnələri hər uğurlu yeniləmədən sonra avtomatik silinir. Qalan yeganə tam ehtiyat nüsxə heç vaxt silinə bilməz — həmişə geri dönmə yolunuz qalır.',
'Upd_Guide_Manual_Title' => '5. Əl ilə yeniləmə (ehtiyat üsul)',
'Upd_Guide_Manual_Text' => 'Əl ilə yeniləməyə üstünlük verirsinizsə və ya yükləyici serverinizdə istifadə edilə bilmirsə, bu səhifənin {tab} tabındakı addım-addım təlimatlara əməl edin.',
'Upd_Guide_Clear_Cache_First' => 'Hər hansı yeniləmədən sonra səhifələr pozulmuş və ya boş görünürsə, əvvəlcə brauzer keşini təmizləyin — demək olar ki, həmişə səbəb budur.',
'Upd_Restore_Backup_Confirm' => 'Bu ehtiyat nüsxə bərpa edilsin? Cari fayllar və cari verilənlər bazası ehtiyat nüsxə ilə əvəz ediləcək. Əvvəlcə cari verilənlər bazasının təhlükəsizlik nüsxəsi götürülür. (v{version} — {date})',
'Woo_Guide_Lead' => 'WooCommerce mağazası ERP ilə necə uyğun qalır. Aşağıdakı cron sətirləri bu server üçün hazırlanıb, buna görə birbaşa ona kopyalana bilər.',
'Woo_Guide_Ways_Note' => 'Shopify-dan fərqli olaraq, WooCommerce ERP-yə öz-özünə heç nə göndərmir — burada webhook qəbuledicisi yoxdur, buna görə {in} hər şey cədvəl üzrə daxil olur. Yalnız {out} stok dərhal ola bilər.',
'Woo_In' => 'gələn',
'Woo_Out' => 'çıxan',
'Woo_Guide_Both_Ways_Title' => 'Hər iki istiqamət üçün əvvəlcə bu lazımdır',
'Woo_Api_Keys' => 'API açarları',
'Woo_Guide_Api_Keys_Text' => '{path}, icazə {perm}. Consumer key və secret dəyərlərini mağaza URL-i ilə birlikdə {settings} tabına kopyalayın — saytınızın sonunda kəsr xətti olmayan ünvanı, məs. {example}.',
'Woo_Credentials_Saved' => 'məlumatlar saxlanılıb',
'Woo_Not_Configured_Yet' => 'hələ qurulmayıb',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress tətbiq parolu (istəyə bağlı)',
'Woo_Guide_Wp_App_Password_Text' => 'Yalnız məhsul şəkilləri üçün istifadə olunur. WooCommerce API məhsulları, stoku, kateqoriyaları, brendləri, müştəriləri və sifarişləri ötürür; WordPress API isə Media kitabxanasında axtarış edən və hələ orada olmayan şəkli yükləyəndir.',
'Woo_Guide_Wp_App_Password_Note' => 'Medianı idarə edə bilən WordPress istifadəçisindən istifadə edin və parolu {path} bölməsində yaradın. Hər iki sahəni boş saxlasanız, hər şey yenə də sinxronlaşır — yalnız şəkil əlavəsi ötürülür.',
'Woo_Guide_Pick_Way_Title' => 'Sonra necə uyğun qalacağını seçin',
'Woo_Right_Away' => 'Dərhal',
'Woo_Stock_Live' => 'stok canlı',
'Woo_Stock_Not_Live' => 'stok canlı deyil',
'Woo_Guide_Realtime_Lead' => 'Yalnız bir istiqamət: ERP-dən çıxan stok və məhsullar. WooCommerce-də edilən sifarişlər və məhsul dəyişiklikləri yenə də cədvəl üzrə gəlir — digər taba baxın.',
'Woo_Push_Stock_On_Change' => 'Stoku dəyişdiyi anda göndər',
'Woo_Setting_People_Miss' => 'Bu, insanların gözdən qaçırdığı parametrdir',
'Woo_Guide_Pos_Sale_Not_Reach' => 'POS satışı WooCommerce-ə öz-özünə {not}. Söndürülmüş halda mağaza bundan yalnız növbəti stok sinxronizasiyasında xəbər tutur — defolt olaraq bir saat — və bu müddətdə kassada artıq satdığınız vahidi sata bilər.',
'Woo_Does_Not' => 'çatmır',
'Woo_Guide_Tick_Instant' => '{settings} tabında {option} seçimini işarələyin. Bütün quraşdırma budur — nə worker, nə cron. Bundan sonra hər satış, qaytarma, düzəliş, köçürmə və qəbul edilmiş alış satış saxlanılan kimi yalnız həmin məhsulları göndərir və iyirmi sətirli satış iyirmi deyil, bir göndərişə başa gəlir. Kassa heç vaxt onu gözləmir.',
'Woo_Currently' => 'Hazırda:',
'Woo_Instant_On_Text' => 'açıq — stok dəyişdikdə göndərilir',
'Woo_Instant_Off_Text' => 'bağlı — stok yalnız cədvəl üzrə',
'Woo_Guide_Instant_Note' => 'Yalnız artıq WooCommerce ilə əlaqələndirilmiş məhsullar göndərilir — heç vaxt sinxronlaşdırılmamış məhsulun mağazada düzəldiləcək heç nəyi yoxdur. Variantlı məhsullar ana məhsul vasitəsilə gedir və kombo onun hər hansı komponenti hərəkət etdikdə yenidən göndərilir. Kütləvi əməliyyatlar (məhsulun silinməsi, anbarın sıfırlanması) stoku hadisə yaratmadan yazır — saatlıq stok sinxronizasiyasını da saxlamağın bir səbəbi budur.',
'Woo_Push_Products_On_Save' => 'Məhsulları saxlanıldığı anda göndər',
'Woo_Guide_Tick_Auto_Products' => '{settings} tabında {option} seçimini işarələyin və Stocky-də yaradılan, redaktə edilən və ya dublikat edilən məhsul saxlanıldıqdan dərhal sonra WooCommerce-ə göndərilir — məlumatlar, qiymət, variantlar və şəkillər, sonra isə stoku. Yeni məhsul gecəlik məhsul sinxronizasiyasını gözləmədən mağazada dərhal yaradılır.',
'Woo_On' => 'açıq',
'Woo_Off' => 'bağlı',
'Woo_Guide_Bulk_Imports_Note' => 'Kütləvi idxallar bir-bir göndərilmir — idxaldan sonra məhsul sinxronizasiyasını işə salın. Göndərilən məhsulun düzgün kateqoriyaya düşməsi üçün əvvəlcə kateqoriyaları və brendləri sinxronlaşdırın.',
'Woo_Nothing_Else_To_Install' => 'Başqa heç nə quraşdırmaq lazım deyil',
'Woo_Guide_Same_Process' => 'Nə növbə worker-i, nə cron qeydi. Göndəriş satışa xidmət edən eyni prosesdə, cavab geri göndərildikdən {after} işləyir, buna görə kassa heç vaxt WooCommerce-i gözləmir. Göndərişlər heç vaxt üst-üstə düşmür: biri işləyərkən edilən dəyişikliklər onu gözləyir və dərhal ondan sonra göndərilir.',
'Woo_After' => 'sonra',
'Woo_Guide_Shop_Stops_Answering' => 'Cavab verməyi dayandıran mağazadan səkkiz saniyədən sonra imtina edilir və göndərişlər beş dəqiqəlik fasilə verir ki, hər satış yenidən onu gözləməsin; bu arada gələn dəyişikliklər fasilədən sonrakı ilk göndərişlə gedir və saatlıq stok sinxronizasiyası hər halda çatışmayanı tamamlayır. Hər fasilə Jurnallar tabında qeyd olunur.',
'Woo_Guide_Artisan_Exception' => 'Bir istisna: artisan əmri ilə edilən stok dəyişikliyinin sonra gələcəyi cavab yoxdur, buna görə o, əvəzində {queue} növbəsinə qoyulur. Onların da tez göndərilməsi üçün həmin növbəni boşaldın:',
'Woo_Cron_Line_Copied' => 'Cron sətri kopyalandı',
'Woo_Command_Copied' => 'Əmr kopyalandı',
'Woo_Guide_Not_Woo_Queue' => 'Qəsdən {queue} növbəsi deyil: o, saatlarla davam edən kataloq partiyalarını daşıyır və onlardan birinin arxasında növbəyə qoyulan dərhal göndəriş dərhal olmazdı.',
'Woo_On_A_Schedule' => 'Cədvəl üzrə',
'Woo_Guide_Scheduled_Lead' => 'Hər şey müəyyən aralıqlarla hər iki istiqamətdə yenidən yoxlanılır. Sifarişlər ERP-yə belə çatır, kataloq belə dərc olunur və sürətli yolun buraxdığı hər şey belə düzəldilir. Hər tapşırığın öz cron qeydi var, buna görə yalnız istədiyinizi işə salırsınız.',
'Woo_Guide_Sync_Drains_Queue' => '{command} işləyərkən öz növbəsini boşaldır, buna görə bu sətirlərə ayrıca worker lazım deyil. Windows-da Task Scheduler-dən {program} proqramı və eyni arqumentlərlə, {path} qovluğunda başladılmaqla istifadə edin.',
'Woo_Or_No_Cron' => 'Və ya ümumiyyətlə cron olmadan',
'Woo_Guide_No_Cron_Text' => 'Buradakı hər tab tələb əsasında sinxronlaşır və əl ilə sinxronizasiya səhifə açıq olduğu müddətdə öz partiyalarını boşaldır — buna görə kiçik mağaza heç bir cron qeydi olmadan işləyə bilər. İtirdiyiniz, heç kim baxmayanda baş verən hər şeydir: sifarişlər yalnız kimsə düyməni basdıqda gəlir.',
'Woo_Commands_Worth_Knowing' => 'Bilməyə dəyən əmrlər',
