'Shopify_Hook_Note_Register' => 'Qeydiyyat Shopify-da abunələri yaradır və onları avtomatik olaraq bu ünvana yönləndirir. Onu Shopify → Settings → Notifications → Webhooks bölməsində əl ilə əlavə etməyin: onlar fərqli secret ilə imzalanır və hər çatdırılma rədd ediləcək.',
