'Shopify_Hook_Retries' => 'Shopify 2xx alana qədər təkrar cəhd edir və hər çatdırılma bir dəfə qeyd olunur — təkrarlanan hadisə dublikat sifariş deyil, heç nə etməyən əməliyyatdır.',
