'Shopify_G_Lead_Store' => 'Bu mağazanın uyğun qalması üçün nəyə ehtiyacı var. Buradakı hər şey bu mağazaya xasdır — yollar və id-lər realdır, buna görə əmrlər birbaşa serverə kopyalana bilər.',
'Shopify_G_Lead_Generic' => 'Shopify mağazası ERP ilə necə uyğun qalır. Onun öz vəziyyətini görmək üçün yuxarıda mağaza seçin və ya olduğu kimi oxuyun — hansı mağazanı qoşmağınızdan asılı olmayaraq cron sətri və webhook URL-i eynidir.',
'Shopify_G_Ways_Note' => 'Əksər mağazalar hər ikisini işlədir: birincisi mağazanı dəqiqəbədəqiqə aktual saxlayır, ikincisi birincinin buraxdığını tutur — heç vaxt gəlməyən webhook, birbaşa Shopify admin panelində edilən dəyişiklik, saytın işləmədiyi gecə.',
'Shopify_G_Both_Need' => 'Hər iki istiqamət üçün əvvəlcə bu lazımdır',
'Shopify_G_Credentials' => 'Shopify giriş məlumatları',
'Shopify_G_Cred_Intro' => '2026-cı ilin yanvarından Shopify artıq admin panelində fərdi tətbiqlər yaratmır, buna görə iki növ bağlantı var:',
'Shopify_G_Cred_DevDash' => '{app} (indi qoşulan istənilən mağaza) — {path}. Bu mağazanın sinxronlaşdırdıqları üçün Admin API əhatələrini verin, tətbiqi mağazaya quraşdırın, sonra tətbiqin Settings səhifəsindən {clientId} və {clientSecret} dəyərlərini {where} kopyalayın. ERP onları giriş tokeninə özü dəyişir və hər 24 saatdan bir müddəti bitməzdən əvvəl yeniləyir. Client secret webhook-ları da imzalayır, buna görə başqa heç nə lazım deyil. Tətbiq və mağaza eyni Shopify təşkilatında olmalıdır.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard tətbiqi',
'Shopify_G_Cred_Legacy' => '{app} (2026-dan əvvəl admin panelində yaradılıb) — öz {token} ({prefix}) və webhook imza secret-i kimi {secret} ilə dəyişmədən işləməyə davam edir. Bu, tokenlə eyni dəyər deyil və onları qarışdırmaq webhook-ların rədd edilməsinin adi səbəbidir.',
'Shopify_G_Legacy_App' => 'Köhnə fərdi tətbiq',
'Shopify_G_API_Secret_Key' => 'API gizli açarı',
'Shopify_G_Stored' => 'saxlanılıb',
'Shopify_G_Missing_Refused' => 'yoxdur — çatdırılmalar rədd ediləcək',
'Shopify_G_Where_Data_Desc' => '{path} Bu mağazanın stokunu satdığı ERP anbarı və həmin stokun yazıldığı Shopify məkanı. İnventar sinxronizasiyası və sifariş idxalı onlarsız işləməkdən imtina edir.',
'Shopify_G_Currently' => 'Hazırda: anbar {warehouse}, məkan {location}',
'Shopify_G_Not_Set_Lower' => 'təyin edilməyib',
'Shopify_G_Ready' => 'hazırdır',
'Shopify_G_Incomplete' => 'natamam',
'Shopify_G_Manual_Syncs' => 'Əl ilə başlatdığınız sinxronizasiyalar',
'Shopify_G_Manual_Desc' => '{centre} bölməsindən başladılan sinxronizasiya dərhal cavab verir və fonda, hər biri sonuncunun dayandığı yerdən davam edən qısa hissələrlə işləyir. Uzun veb sorğuları kəsən hostinq (LiteSpeed, nginx, yük balanslaşdırıcı) böyük kataloqu heç vaxt yarıda kəsmir və səhifəni bağlamaq onu dayandırmır. Bunun üçün worker daha bir cron sətridir:',
'Shopify_G_Cron_Copied' => 'Cron sətri kopyalandı',
'Shopify_G_Manual_Note' => 'Onsuz sinxronizasiya yenə də başa çatır, lakin yalnız Sinxronizasiya Mərkəzi səhifəsi açıq qaldığı müddətdə: heç bir worker icranı bir neçə saniyə ərzində götürmədikdə, səhifə onu özü, bir-bir qısa sorğularla davam etdirir. Windows-da hər dəqiqə Task Scheduler istifadə edin: proqram {program}, arqumentlər {args}, {dir} qovluğunda başladılmaqla.',
'Shopify_G_Then_Pick' => 'Sonra necə uyğun qalacağını seçin',
'Shopify_G_Right_Away' => 'Dərhal',
'Shopify_G_Stock_Live' => 'stok canlı',
'Shopify_G_Stock_Not_Live' => 'stok canlı deyil',
'Shopify_G_Realtime_Lead' => 'Hər dəyişiklik baş verdiyi anda, saniyələr ərzində göndərilir. İki hissə var və onlar ayrı açarlardır: {webhooks} mağazanın öz hadisələrini daxil gətirir, {push} isə stoku xaricə göndərir.',
'Shopify_G_Webhooks_Lower' => 'webhook-lar',
'Shopify_G_Instant_Push_Lower' => 'dərhal stok göndərişi',
'Shopify_G_Webhooks_In' => 'Webhook-lar — mağaza → ERP',
'Shopify_G_Webhooks_Desc' => 'Shopify-da edilən sifarişlər, sifariş statusu dəyişiklikləri və məhsul, müştəri və stok dəyişiklikləri. Mağazanı açın və onun {tab} bölməsində {button} düyməsini basın — iki dəfə basmaq təhlükəsizdir. Shopify bura göndərir:',
'Shopify_G_Webhooks_Tab' => 'Webhooks tabı',
'Shopify_G_Webhooks_Note' => 'Ünvan internetdən HTTPS üzərindən əlçatan olmalıdır — Shopify {localhost} və ya {test} domeninə çatdırmır. Hər çatdırılma bir dəfə qeyd olunur, buna görə Shopify-ın təkrar cəhdləri dublikat sifariş yarada bilməz, uğursuz olanı isə təkrar oynatmaq olar. 1-ci addımdakı imza secret-i saxlanılana qədər çatdırılmalar rədd edilir.',
'Shopify_G_Instant_Out' => 'Dərhal stok göndərişi — ERP → mağaza',
'Shopify_G_Setting_Missed' => 'Bu, insanların gözdən qaçırdığı parametrdir',
'Shopify_G_Pos_Not_Auto' => 'POS satışının Shopify-a öz-özünə çatma imkanı {not}. Söndürülmüş halda mağaza bundan yalnız növbəti İnventar göndərişi addımında xəbər tutur — və bu müddətdə kassada artıq satdığınız vahidi sata bilər.',
'Shopify_G_Not' => 'yoxdur',
'Shopify_G_Tick_Push' => '{where} bölməsində {setting} işarələyin. Bütün quraşdırma budur — nə worker, nə cron. Bundan sonra hər satış, qaytarma və düzəliş satış saxlanılan kimi yalnız həmin məhsulları göndərir və iyirmi sətirli satış iyirmi deyil, bir göndərişə başa gəlir. Kassa heç vaxt onu gözləmir.',
'Shopify_G_This_Store' => 'Bu mağaza:',
'Shopify_G_Push_On' => 'açıq — stok dəyişdikdə göndərilir',
'Shopify_G_Push_Off' => 'bağlı — stok yalnız cədvəl üzrə',
'Shopify_G_Push_Note' => 'Yalnız artıq Shopify uyğunlaşdırması olan məhsullar və yalnız bu mağazanın anbarındakı hərəkətlər göndərilir. Kütləvi əməliyyatlar — məhsulun silinməsi, anbarın sıfırlanması — stoku hadisə yaratmadan yazır, planlaşdırılmış inventar addımını da saxlamağın bir səbəbi budur.',
'Shopify_G_Nothing_Install' => 'Başqa heç nə quraşdırmaq lazım deyil',
'Shopify_G_No_Worker_Note' => 'Heç bir hissəyə növbə worker-i və ya cron qeydi lazım deyil. Gələn webhook Shopify-ın etdiyi sorğuda işlənir; çıxan stok göndərişi satışa xidmət edən eyni prosesdə, cavab geri göndərildikdən {after} işləyir — buna görə kassa heç vaxt Shopify-ı gözləmir, cavab verməyi dayandıran mağazadan isə on saniyədən sonra imtina edilir və o, növbəti planlaşdırılmış inventar göndərişinə buraxılır.',
'Shopify_G_After' => 'sonra',
'Shopify_G_Artisan_Note' => 'Bir istisna: artisan əmri ilə edilən stok dəyişikliyinin sonra gələcəyi cavab yoxdur, buna görə o, əvəzində {queue} növbəsinə qoyulur. Onların da tez göndərilməsini istəyirsinizsə, həmin növbəni boşaldın:',
'Shopify_G_On_Schedule' => 'Cədvəl üzrə',
'Shopify_G_On_Lower' => 'açıq',
'Shopify_G_Off_Lower' => 'bağlı',
'Shopify_G_Scheduled_Lead' => 'Hər şey müəyyən aralıqlarla hər iki istiqamətdə yenidən yoxlanılır. Real vaxtdan yavaşdır, lakin dərhal göndərişdən istifadə etməyən mağazalarda stoku göndərən, buraxılmış webhook-u tutan və bütöv kataloqu ötürməyin yeganə yolu budur.',
'Shopify_G_Cron_Entry' => 'Cron qeydi',
'Shopify_G_Cron_Entry_Desc' => 'Onsuz heç bir planlaşdırılmış şey işləmir. Bir sətir, yalnız bu modul üçün — onu planlaşdırmaq üçün seçdiyiniz digər şeylərin yanına əlavə edin:',
'Shopify_G_Cron_Note' => 'Planın istifadə edə biləcəyi ən dəqiq addım hər beş dəqiqədir, çünki beş dəqiqə ən qısa addım intervalıdır. Daha seyrək qeyd sadəcə minimum olur — {example} ilə 5 dəqiqəyə təyin edilmiş addım hər 15 dəqiqədən bir işləyir. Windows-da Task Scheduler istifadə edin: proqram {program}, arqumentlər {args}, {dir} qovluğunda başladılmaqla.',
'Shopify_G_Switch_On_Plan' => 'Aktivləşdirin və planı seçin',
'Shopify_G_Plan_Desc' => '{where} Açar cron-un ümumiyyətlə işləyə bilib-bilməyəcəyini, plan isə nə edəcəyini müəyyən edir. {step} öz intervalı ilə bir istiqamətdə bir obyektdir — {first}, {second}. Defolt interval öz xanasını boş saxlayan istənilən addım tərəfindən istifadə olunur.',
'Shopify_G_Step_Lower' => 'Addım',
'Shopify_G_Plan_Note' => 'Planı boş saxlayın və mağaza defolt intervalla sifarişləri çəkir və stoku göndərir — əksər mağazaların istədiyi budur. Sifarişlər yalnız çəkilir: müştəri sifarişi Shopify-da verir.',
'Shopify_G_Schedule_On' => 'cədvəl açıq',
'Shopify_G_Schedule_Off' => 'cədvəl bağlı — yalnız əl ilə',
'Shopify_G_When_Step_Runs' => 'Addım əslində nə vaxt işləyir',
'Shopify_G_When_Note' => 'Addım, həmin addımın sonuncu dəfə {started} vaxtdan onun intervalından çox vaxt keçdikdə icraya hazır sayılır; bu, icra tarixçəsindən oxunur. Beləliklə, əl ilə başlatdığınız sinxronizasiya növbəti avtomatik icranı təxirə salır, daim uğursuz olan addım isə hər tikdə deyil, öz intervalı ilə təkrar cəhd edilir. Mağazanın İcmal bölməsi hər addımın son icrasını, növbəti vaxtını və bloklandıqda səbəbini göstərir. İlk kataloq göndərişini cədvələ qoymazdan əvvəl əl ilə işə salın — əvvəlcə {dryRun} ilə.',
'Shopify_G_Started_Lower' => 'başladığı',
'Shopify_G_Where_Setting' => 'Hər parametrin harada olduğu',
'Shopify_G_Where_Setting_Note' => 'Bunların hamısı mövcud mağazadadır: {path}, sonra qələm (və ya mağazanın öz səhifəsində {edit}).',
'Shopify_G_Product_Images' => 'Məhsul şəkilləri',
'Shopify_G_Img_1' => 'Şəkillər {push} zamanı məhsulla birlikdə göndərilir — əvvəlcə əsas şəkil, sonra qalereya, sonra öz şəkli olan hər variant üçün biri, əllisinədək.',
'Shopify_G_Products_Push' => 'məhsul göndərişi',
'Shopify_G_Img_2' => 'Variantın şəkli məhsulla birlikdə yüklənir və sonra {assigned} — Shopify bunu belə modelləşdirir: variant məhsulun şəkillərindən birinə istinad edir. Əsas şəkli təkrar istifadə edən variant onu iki dəfə yükləmir.',
'Shopify_G_Assigned' => 'həmin varianta təyin edilir',
'Shopify_G_Img_3' => 'Fayl kimi saxlanılan şəkil Shopify-a keçid kimi deyil, {uploaded}, buna görə bu quraşdırma internetdən əlçatan olmadıqda belə işləyir. Yapışdırılmış keçid kimi əlavə edilən şəkil Shopify-a həmin URL kimi ötürülür və o, ictimai əlçatan olmalıdır.',
'Shopify_G_Uploaded' => 'yüklənir',
'Shopify_G_Img_4' => 'Onlar yalnız həqiqətən dəyişdikdə yenidən göndərilir — yalnız qiyməti dəyişən göndəriş mağazanın şəkillərinə toxunmur, çünki onları göndərmək bütün dəsti əvəz edir.',
'Shopify_G_Img_5' => 'ERP-də şəkli silməyin Shopify-da onu silmə təsiri {not}. Onu orada da silin, əks halda mağaza onu göstərməyə davam edir.',
