'Cr_Guide_S_cancelled' => 'Sifariş ləğv edilib.',
'Cr_Guide_T_Booking' => 'Sifarişlərin kuryerə verilməsi',
'Cr_Guide_B_Booking' => 'Kuryerə göndər formu satışdan doldurur: alıcı, ünvan, COD kimi hələ ödənilməmiş məbləğ və məhsulların çəkisi. Öz şəhər siyahısı olan kuryerlər seçici göstərir və seçiminiz həmin şəhər üçün yadda saxlanılır. Aqreqatorlar, DHL, FedEx, UPS və Lalamove Tarifləri müqayisə et funksiyasını təklif edir: qiymət seçin və Sifariş et onu alır. Satışlar siyahısından bir neçə satışı birdən kuryerə vermək olar.',
'Cr_Guide_T_Cod' => 'Çatdırılma zamanı ödəniş',
'Cr_Guide_B_Cod' => 'COD bağlaması Toplanmayıb statusundan Kuryer tərəfindən toplanıb (çatdırılma zamanı) və Sizə köçürülüb statusuna keçir. Köçürmələri bildirən kuryerlər son addımı özləri keçirir; digərləri üçün COD-u yenilə istifadə edin. Kuryer parametrlərində hesab seçilibsə, köçürmə satışda ödəniş kimi qeyd olunur. Bağlama tamamlandıqdan sonra kuryer haqları xərc kimi saxlanıla bilər.',
'Cr_Guide_T_Returns' => 'Qaytarılmış bağlamalar',
'Cr_Guide_B_Returns' => 'Standart olaraq qaytarılmış bağlama Kuryer göndərişlərində Yoxlanılacaq qaytarmalar altında gözləyir. Stoka qaytar bütün sifariş üçün satış qaytarması yaradır və malları yenidən stoka qaytarır; Rədd et isə zədələnmiş və ya itmiş bağlamalar üçün heç nə qaytarmır. Əvəzində Kuryer parametrləri avtomatik stoka qaytara bilər.',
'Cr_Guide_T_Customers' => 'Müştəri mesajları və izləmə səhifəsi',
'Cr_Guide_B_Customers' => 'Kuryer parametrlərindəki müştəri bildirişləri işarələdiyiniz statuslarda öz mətninizlə SMS, e-poçt və ya WhatsApp göndərir, hər biri bağlama başına bir dəfə. Onlayn mağazanızdakı izləmə səhifəsi müştərilərə bağlamanı izləmə nömrəsi və ya sifariş nömrəsi və telefonla izləməyə imkan verir. Tez-tez bağlama qaytaran müştərilər sifariş verərkən qaytarma riski nişanı alır.',
'Cr_Guide_T_Labels' => 'Etiketlər',
'Cr_Guide_B_Labels' => 'Etiketi çap et kuryer öz etiketini verirsə (PDF, keçid və ya şəkil) onu, əks halda izləmə barkodu və toplanacaq məbləğlə Stocky etiketini verir. Çap etmək üçün bu sayt üçün açılan pəncərələrə icazə verin. DHL, FedEx və UPS etiketlərini yalnız bir dəfə, sifariş zamanı verir və Stocky onu təkrar çap üçün saxlayır.',
'Cr_Guide_T_Faq' => 'Problemlərin həlli',
'Cr_Guide_Q_Test' => 'Bağlantı testi uğursuz olur',
'Cr_Guide_A_Test' => 'Test rejimi açarları Test rejimi ilə, canlı açarlar isə Canlı ilə işləyir; onlar fərqlidir. Dəqiq səbəbi öyrənmək üçün Kuryer jurnallarını açın və kuryerin cavabını oxuyun.',
'Cr_Guide_Q_City' => 'Kuryer şəhəri və ya ünvanı rədd edir',
'Cr_Guide_A_City' => 'Sifariş formunda şəhəri kuryer şəhər siyahısından seçin; kuryerlər yalnız öz adlarını qəbul edir. Poçt ünvanları ilə işləyən kuryerlərə həmçinin ştat, poçt indeksi və iki hərfli ölkə kodu lazımdır.',
'Cr_Guide_Q_Webhook' => 'Statuslar özbaşına dəyişmir',
