'Tfa_Codes_Save' => 'Bu bərpa kodlarını təhlükəsiz yerdə saxlayın. Telefonunuzu itirsəniz, hər biri sizi bir dəfə daxil edir. Onlar bir daha göstərilməyəcək.',
'Tfa_Reset' => 'İki faktorlunu sıfırla',
'Tfa_Reset_Title' => 'İki faktorlu autentifikasiya sıfırlansın?',
'Tfa_Reset_Help' => ':name yalnız parolu ilə daxil olacaq və sonra autentifikator tətbiqini yenidən quraşdıra bilər. Bunu yalnız kimin müraciət etdiyini təsdiqlədikdən sonra edin.',
'Tfa_Guide_Lead' => 'İki faktorlu autentifikasiya (2FA) girişə ikinci addım əlavə edir: paroldan sonra işçilər telefonlarındakı autentifikator tətbiqindən 6 rəqəmli kod daxil edirlər. Oğurlanmış və ya təxmin edilmiş parol artıq daxil olmaq üçün kifayət etmir.',
