'Tfa_Guide_State_Users' => '2FA aktiv olan istifadəçilər',
'Tfa_Guide_Staff_Title' => 'Hər bir işçi üçün',
'Tfa_Guide_App_Title' => 'Autentifikator tətbiqi quraşdırın',
'Tfa_Guide_App_Text' => 'Standart 6 rəqəmli kodları (TOTP) dəstəkləyən istənilən tətbiq işləyir. Onlar pulsuzdur və oflayn işləyir:',
'Tfa_Guide_Enable_Title' => 'Profildən aktivləşdirin',
'Tfa_Guide_Enable_1' => 'Profili açın (yuxarı sağdakı avatar menyusu) və "İki faktorlu autentifikasiya" kartını tapın.',
'Tfa_Guide_Enable_2' => '"Aktivləşdir" düyməsinə klikləyin və cari parolla təsdiqləyin.',
'Tfa_Guide_Enable_3' => 'QR kodu tətbiqlə skan edin və ya onun altında göstərilən açarı daxil edin.',
'Tfa_Guide_Enable_4' => 'Tamamlamaq üçün tətbiqin göstərdiyi 6 rəqəmli kodu daxil edin.',
'Tfa_Guide_Open_Profile' => 'Profilimi aç',
'Tfa_Guide_Codes_Title' => 'Bərpa kodlarını saxlayın',
'Tfa_Guide_Codes_Text' => 'Quraşdırmadan dərhal sonra 8 bərpa kodu bir dəfə göstərilir. Hər biri telefon kodunu bir dəfə əvəz edir — itirilmiş, sınmış və ya sıfırlanmış telefon üçün. Onları yükləyin və ya kopyalayın və telefondan uzaq, təhlükəsiz yerdə saxlayın.',
'Tfa_Guide_Codes_Note' => 'Kodlar azalır? Profildəki "Yeni bərpa kodları" bütün dəsti əvəz edir; köhnələr işləməyi dayandırır.',
'Tfa_Guide_Signin_Title' => 'Giriş',
'Tfa_Guide_Signin_Text' => 'E-poçt və paroldan sonra giriş səhifəsi tətbiqdəki cari kodu soruşur. Kodlar hər 30 saniyədən bir dəyişir və hər biri bir dəfə işləyir.',
'Tfa_Guide_Signin_Trust' => '"Bu cihazda yenidən soruşma" seçimini işarələmək həmin brauzerdə :days gün ərzində kodu ötürür.',
'Tfa_Guide_Signin_Recovery' => 'Telefon yanınızda deyil? "Bərpa kodundan istifadə et" düyməsinə klikləyin və saxlanılmış kodlardan birini daxil edin.',
'Tfa_Guide_Admin_Title' => 'Administratorlar üçün',
'Tfa_Guide_Require_Title' => 'Məcburi edin',
'Tfa_Guide_Require_Text' => 'Bu kartda "İki faktorlu autentifikasiyanı tələb et" seçimini aktivləşdirin, sonra onu istifadə etməli olan rolları seçin — və ya bütün istifadəçilər üçün siyahını boş buraxın. Yadda saxlamaq üçün Göndər düyməsinə klikləyin.',
'Tfa_Guide_Require_Next' => 'Heç kim sistemdən çıxarılmır. Hələ 2FA-sı olmayan istifadəçilər növbəti girişlərində, daxil olmazdan əvvəl giriş səhifəsində quraşdırma addımlarından keçirilir və bərpa kodlarını orada görürlər.',
'Tfa_Guide_Require_Note' => 'Tələb olunan istifadəçilər onu profillərindən söndürə bilməz.',
'Tfa_Guide_Trust_Title' => 'Etibarlı cihazlar',
'Tfa_Guide_Trust_Text' => '"Etibarlı cihazları yadda saxla" uğurlu girişdən sonra brauzerin nə qədər müddət kodu ötürə biləcəyini müəyyən edir. Mağaza zalındakı POS kimi ortaq və ya ictimai kompüterlər üçün "Həmişə kod soruş" seçin.',
'Tfa_Guide_Trust_Note' => 'Rəqəmi azaltmaq artıq etibarlı olan cihazların müddətini qısaldır; 2FA-nı söndürmək və ya sıfırlamaq hamısını unudur.',
'Tfa_Guide_Lost_Title' => 'Telefon itib və bərpa kodları yoxdur',
'Tfa_Guide_Lost_Text' => 'İstifadəçilər səhifəsində 2FA-sı olan istifadəçilər 2FA sütununda "Aktiv" göstərir. Əməliyyatlardakı qalxan düyməsi onu sıfırlayır: istifadəçi yalnız parolla daxil olur və tətbiqi yenidən quraşdırır (tələb olunursa, bu ondan istənilir).',
'Tfa_Guide_Lost_Warn' => 'Sıfırlamazdan əvvəl kimin müraciət etdiyini təsdiqləyin — sıfırlama 2FA-nın həmin hesaba verdiyi qorunmanı aradan qaldırır.',
'Tfa_Guide_Open_Users' => 'İstifadəçiləri aç',
'Tfa_Guide_Mobile_Title' => 'Mobil tətbiq və API',
'Tfa_Guide_Mobile_Text' => 'Mobil tətbiq və API token endpoint-i eyni kodu soruşur. 2FA hələ quraşdırmamış istifadəçi üçün tələb olunursa, bunu etmək üçün o, bir dəfə veb vasitəsilə daxil olmalıdır.',
'Tfa_Guide_Protect_Title' => 'Daxili qorunma',
'Tfa_Guide_Protect_1' => '5 yanlış kod, yuxarıdakı bloklama parametrlərindən asılı olmayaraq, həmin istifadəçi üçün kod daxil etməni 15 dəqiqəlik bloklayır.',
'Tfa_Guide_Protect_2' => 'Hər kod və hər bərpa kodu yalnız bir dəfə işləyir.',
'Tfa_Guide_Protect_3' => '"Giriş fəaliyyətini qeyd et" aktiv olduqda, yanlış kodlar Giriş fəaliyyəti siyahısında "Yanlış 2FA kodu" kimi görünür.',
'Tfa_Guide_Trouble_Title' => 'Problemlərin həlli',
'Tfa_Guide_Faq_Clock_Q' => 'Yeni kodla “Bu kod etibarlı deyil”',
'Tfa_Guide_Faq_Clock_A' => 'Çox güman ki, telefonun saatı düzgün deyil. Kodlar vaxtdan asılıdır: telefonun tarix və vaxtını avtomatik (şəbəkə vaxtı) edin, sonra növbəti kodu yoxlayın.',
'Tfa_Guide_Faq_Phone_Q' => 'Yeni telefona keçid',
'Tfa_Guide_Faq_Phone_A' => 'Ya autentifikator tətbiqinin öz köçürmə funksiyasından istifadə edin, ya da profildə 2FA-nı söndürüb yeni telefonla yenidən aktivləşdirin (tələb olunursa, əvəzinə administratordan onu sıfırlamasını xahiş edin).',
'Tfa_Guide_Faq_Locked_Q' => '“Həddindən çox yanlış kod”',
'Tfa_Guide_Faq_Locked_A' => 'Göstərilən vaxtı gözləyin (15 dəqiqəyə qədər) və ya administratordan istifadəçinin 2FA-sını sıfırlamasını xahiş edin.',
'Tfa_Guide_Faq_Key_Q' => 'Server köçürüldükdən sonra 2FA-sı olan heç kim daxil ola bilmir',
'Tfa_Guide_Faq_Key_A' => '2FA sirləri .env faylındakı APP_KEY ilə şifrələnir. Tətbiqi köçürərkən və ya bərpa edərkən eyni APP_KEY-i saxlayın; dəyişibsə, 2FA-sı olmayan administrator təsirlənmiş istifadəçiləri sıfırlamalıdır.',
'Tfa_Guide_Button' => 'Bələdçi',
'Tfa_Guide_Title' => 'İki faktorlu autentifikasiya bələdçisi',
'Sec_2fa_Pending' => ':count nəfər hələ quraşdırmalıdır',
'Sec_2fa_See_Who' => 'Kim olduğunu gör',
'Sec_2fa_Grace_Off' => 'Yoxdur — növbəti girişdə quraşdırılsın',
'Sec_2fa_Applied' => ':count istifadəçi sistemdən çıxarıldı.',
'Tfa_Guide_Rollout_Title' => 'Bütün istifadəçilər üçün tətbiq edin',
'Tfa_Guide_Rollout_1' => 'Addımları bilmək üçün əvvəlcə öz hesabınız üçün aktivləşdirin (Profil).',
'Tfa_Guide_Rollout_2' => 'Komandanıza hansı tətbiqi quraşdırmalı olduqlarını və quraşdırmanın girişdə bir dəqiqə çəkdiyini bildirin.',
'Tfa_Guide_Rollout_3' => '"İki faktorlu autentifikasiyanı tələb et" seçimini aktivləşdirin, "Tələb olunur" sahəsini boş buraxın (= bütün istifadəçilər) və istəyə görə güzəşt müddəti seçin. Göndər düyməsinə klikləyin.',
'Tfa_Guide_Rollout_4' => 'Artıq daxil olmuş şəxslərin onu sonrakı hansısa girişdə deyil, indi quraşdırması üçün "2FA-sız istifadəçiləri sistemdən çıxar" düyməsinə klikləyin. Siz sistemdə qalırsınız.',
'Tfa_Guide_Rollout_5' => 'İrəliləyişi bu kartdakı sayğac və ya İstifadəçilər səhifəsindəki "Quraşdırma tələb olunur" filtri ilə izləyin.',
'Tfa_Guide_Rollout_Note' => 'Güzəşt müddəti olduqda, quraşdırma ekranı son tarixə qədər “Sonra xatırlat” seçimini göstərir; ondan sonra daxil olmaq üçün quraşdırma tələb olunur.',
'Tfa_Guide_Customers_Title' => 'Müştəri hesabları (mağaza və müştəri portalı)',
'Tfa_Guide_Customers_Text' => 'Müştərilər də öz hesablarını qoruya bilərlər. Bu, hər müştəri üçün istəyə bağlıdır və heç vaxt məcburi edilmir: onu Mağaza parametrləri → Qeydiyyat girişinə nəzarət (onlayn mağaza) və Müştəri portalı → Portal parametrləri (müştəri portalı) bölmələrində aktivləşdirin.',
'Tfa_Guide_Customers_1' => 'Müştərilər onu Hesabım (mağaza) və ya Profil (portal) bölməsindən aktivləşdirirlər.',
'Tfa_Guide_Customers_2' => 'Onlar e-poçtla göndərilən kodu — ən asanı, tətbiq lazım deyil — və ya bərpa kodları olan autentifikator tətbiqini seçirlər.',
'Tfa_Guide_Customers_3' => 'E-poçtla göndərilən kodlar işlək poçt parametrləri tələb edir (Parametrlər → Poçt parametrləri). Onların müddəti 10 dəqiqədən sonra bitir.',
'Tfa_Guide_Customers_4' => 'Seçimi sonradan söndürmək yeni quraşdırmaları dayandırır; onu artıq istifadə edən müştərilərdən kod soruşulmağa davam edir və onlar onu özləri söndürə bilərlər.',
'Tfa_Required_Grace_Notice' => 'Administratorunuz iki faktorlu autentifikasiya tələb edir. Girişdə onu :date tarixinə qədər təxirə sala bilərsiniz; bundan sonra quraşdırma tələb olunur.',
'Tfa_Filter_All' => '2FA: bütün istifadəçilər',
'Tfa_Needs_Setup_Help' => 'Sistem parametrləri > Təhlükəsizlik tərəfindən tələb olunur; növbəti girişdə quraşdırması istəniləcək.',
