'Portal_2fa' => 'İki addımlı təsdiqləmə',
'Portal_2fa_Help' => 'Müştərilərə portal girişlərini e-poçtla göndərilən və ya autentifikator tətbiqindən alınan kodla qorumağa imkan verir; profillərindən aktivləşdirilir. Hər müştəri üçün istəyə bağlıdır.',
